mapper.select:
SELECT DISTINCT u.id, u.username, u.display_name, u.department, u.email, u.phone, u.is_active, u.last_login_at, u.created_at, u.updated_at FROM user u LEFT JOIN user_role ur ON u.id = ur.user_id
AND (u.username LIKE CONCAT('%', #{keyword}, '%') OR u.display_name LIKE CONCAT('%', #{keyword}, '%') OR u.department LIKE CONCAT('%', #{keyword}, '%'))
AND u.is_active = #{isActive}
AND ur.role_id = #{roleId}
ORDER BY u.id LIMIT #{offset}, #{limit}

SELECT COUNT(DISTINCT u.id) FROM user u LEFT JOIN user_role ur ON u.id = ur.user_id
AND (u.username LIKE CONCAT('%', #{keyword}, '%') OR u.display_name LIKE CONCAT('%', #{keyword}, '%') OR u.department LIKE CONCAT('%', #{keyword}, '%'))
AND u.is_active = #{isActive}
AND ur.role_id = #{roleId}

